-- Three Hands Healing — owner-editable site (clients/three-hands-healing/).
-- Generated by scripts/gen-migration.mjs from site.config.mjs. Re-run the
-- generator instead of editing by hand; if the site is already live, write a
-- NEW numbered migration for changes.
--
-- Written exclusively through the site's Netlify functions using the service
-- role. RLS is enabled with no policies so anon/authenticated roles cannot
-- touch these rows; the service role bypasses RLS.
--
-- Tables (schema `command`, prefix three_hands_healing_):
--   three_hands_healing_editors       who may log in to /admin/ (owner | editor)
--   three_hands_healing_login_tokens  single-use magic-link tokens (sha256 hashes)
--   three_hands_healing_content       one jsonb document per key ('site')
--   three_hands_healing_media         gallery images, ordered; seed rows below
--   three_hands_healing_revisions     snapshot on every publish (owner-side undo/history)
-- Storage: public bucket `three-hands-healing` for owner uploads.

create table if not exists command.three_hands_healing_editors (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  role text not null default 'editor' check (role in ('owner', 'editor')),
  created_at timestamptz not null default now(),
  last_login_at timestamptz,
  invited_by uuid references command.three_hands_healing_editors(id) on delete set null
);

create unique index if not exists three_hands_healing_editors_email_key
  on command.three_hands_healing_editors (lower(email));

create table if not exists command.three_hands_healing_login_tokens (
  id uuid primary key default gen_random_uuid(),
  editor_id uuid not null references command.three_hands_healing_editors(id) on delete cascade,
  token_hash text not null unique,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  used_at timestamptz,
  request_ip text
);

create index if not exists three_hands_healing_login_tokens_editor_idx
  on command.three_hands_healing_login_tokens (editor_id, created_at desc);

create table if not exists command.three_hands_healing_content (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by uuid references command.three_hands_healing_editors(id) on delete set null
);

create table if not exists command.three_hands_healing_media (
  id uuid primary key default gen_random_uuid(),
  sort integer not null default 0,
  -- storage object path inside the bucket, or a site-relative path
  -- (/img/placeholder/ph-01.svg) for seeded files shipped with the site
  path text not null,
  is_placeholder boolean not null default false,
  alt text not null default '',
  caption text not null default '',
  category text not null default '',
  featured boolean not null default false,
  width integer,
  height integer,
  bytes integer,
  mime text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists three_hands_healing_media_sort_idx
  on command.three_hands_healing_media (sort, created_at);

create table if not exists command.three_hands_healing_revisions (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  editor_id uuid references command.three_hands_healing_editors(id) on delete set null,
  kind text not null check (kind in ('content', 'media')),
  snapshot jsonb not null
);

create index if not exists three_hands_healing_revisions_created_idx
  on command.three_hands_healing_revisions (created_at desc);

alter table command.three_hands_healing_editors enable row level security;
alter table command.three_hands_healing_login_tokens enable row level security;
alter table command.three_hands_healing_content enable row level security;
alter table command.three_hands_healing_media enable row level security;
alter table command.three_hands_healing_revisions enable row level security;

-- Belt and braces: even if a client-side key reaches the API, anon and
-- authenticated get nothing. The service role bypasses RLS.
revoke all on command.three_hands_healing_editors from anon, authenticated;
revoke all on command.three_hands_healing_login_tokens from anon, authenticated;
revoke all on command.three_hands_healing_content from anon, authenticated;
revoke all on command.three_hands_healing_media from anon, authenticated;
revoke all on command.three_hands_healing_revisions from anon, authenticated;

-- Public bucket for owner uploads. Objects are read at
-- /storage/v1/object/public/three-hands-healing/<path>; uploads go through signed
-- upload URLs minted by the service role, so no storage policies are needed.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'three-hands-healing', 'three-hands-healing', true, 15728640,
  array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif']
)
on conflict (id) do nothing;

