-- First editor: the HAND operator inbox, so the site can be tested before the
-- client's own email is added (admin Editors tab or THREE_HANDS_HEALING_OWNER_EMAILS).
insert into command.three_hands_healing_editors (email, role)
values ('hand@handprotocol.org', 'owner')
on conflict do nothing;
